#include <cuda_runtime.h>
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <vector>
#include <algorithm>
#define C(x) do{auto e=(x);if(e){fprintf(stderr,"%s %s\n",#x,cudaGetErrorString(e));exit(2);}}while(0)
struct Slot{void *p,*q,*h;cudaStream_t a,b;cudaEvent_t ready,done;bool used=false;};
int main(){for(int src=0;src<2;src++){int dst=1-src;C(cudaSetDevice(dst));C(cudaDeviceEnablePeerAccess(src,0));for(size_t mb:{size_t(1),size_t(4),size_t(16),size_t(64)})for(int depth:{1,2,4,8}){size_t n=mb<<20;std::vector<Slot> slots(depth);for(int j=0;j<depth;j++){auto &s=slots[j];C(cudaMallocHost(&s.h,n));C(cudaSetDevice(src));C(cudaMalloc(&s.p,n));C(cudaMemset(s.p,0x31+j,n));C(cudaStreamCreateWithFlags(&s.a,cudaStreamNonBlocking));C(cudaEventCreateWithFlags(&s.ready,cudaEventDisableTiming));C(cudaSetDevice(dst));C(cudaMalloc(&s.q,n));C(cudaStreamCreateWithFlags(&s.b,cudaStreamNonBlocking));C(cudaEventCreateWithFlags(&s.done,cudaEventDisableTiming));}C(cudaSetDevice(src));C(cudaDeviceSynchronize());for(int mode=0;mode<2;mode++){int count=std::max(depth*2,int(1024/mb));auto run=[&](){for(auto &s:slots)s.used=false;for(int i=0;i<count;i++){auto &s=slots[i%depth];C(cudaSetDevice(dst));if(s.used)C(cudaEventSynchronize(s.done));if(mode==0){C(cudaMemcpyPeerAsync(s.q,dst,s.p,src,n,s.b));}else{C(cudaSetDevice(src));C(cudaMemcpyAsync(s.h,s.p,n,cudaMemcpyDeviceToHost,s.a));C(cudaEventRecord(s.ready,s.a));C(cudaSetDevice(dst));C(cudaStreamWaitEvent(s.b,s.ready,0));C(cudaMemcpyAsync(s.q,s.h,n,cudaMemcpyHostToDevice,s.b));}C(cudaEventRecord(s.done,s.b));s.used=true;}C(cudaSetDevice(dst));for(auto &s:slots)if(s.used)C(cudaEventSynchronize(s.done));};run();double best=0,sum=0;for(int trial=0;trial<3;trial++){auto start=std::chrono::steady_clock::now();run();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();double gb=double(n)*count/sec/1e9;sum+=gb;best=std::max(best,gb);}std::vector<unsigned char> out(n);size_t bad=0;for(int j=0;j<depth;j++){C(cudaMemcpy(out.data(),slots[j].q,n,cudaMemcpyDeviceToHost));for(auto v:out)bad+=v!=0x31+j;}printf("%d->%d mode=%s chunk_MiB=%zu depth=%d best_GBps=%.3f mean_GBps=%.3f bad=%zu\n",src,dst,mode?"host_pipeline":"p2p",mb,depth,best,sum/3,bad);fflush(stdout);if(bad)return 1;}for(auto&s:slots){C(cudaSetDevice(src));C(cudaFree(s.p));C(cudaStreamDestroy(s.a));C(cudaEventDestroy(s.ready));C(cudaSetDevice(dst));C(cudaFree(s.q));C(cudaStreamDestroy(s.b));C(cudaEventDestroy(s.done));C(cudaFreeHost(s.h));}}}}
